def m(x, d=2):
    if x is None or not np.isfinite(x): return 'n/a'
    s = f'{x:.{d}f}'
    if s.startswith('-'): s = '−' + s[1:]
    if s in ('−0.00', '−0.0'): s = s[1:]
    return s


def rng(lo, hi, d=2): return f'{m(lo, d)} to {m(hi, d)}' if (lo < 0 or hi < 0) else f'{m(lo, d)}–{m(hi, d)}'


def E(key, z='All', d=2, unit=True, ci=True):
    p = S[key][z]; u = ' °C' if unit else ''
    return f"{m(p['mu'], d)}{u} (95% CI {rng(p['lo'], p['hi'], d)}{u})" if ci else f"{m(p['mu'], d)}{u}"


def Ein(key, z='All', d=2):
    p = S[key][z]; return f"{m(p['mu'], d)} °C; 95% CI {rng(p['lo'], p['hi'], d)} °C"


def MU(key, z='All', d=2): return m(S[key][z]['mu'], d)
def CI(key, z='All', d=2): p = S[key][z]; return rng(p['lo'], p['hi'], d)
def B(t, d=2): return f'{m(t[0], d)} ({rng(t[1], t[2], d)})'
def pct(x): return f'{100 * x:.0f}%'
def K(key, z='All'): return S[key][z]['k']


IV = S['intervention']; CH = S['change']; SIM = S.get('sim', {}); PR = S.get('proj', {})
