def tables(D):
    D.table(['Layer and question', 'Estimand or quantity', 'Conditioning set', 'What is held fixed', 'Evidence in this study'],
            [['Prediction: how hot is a place, how did heat change?', 'E[HI | surface, terrain, climate]', 'Any predictors', 'Nothing; association', 'Transfer of 1985–2025 change (Fig. 3)'],
             ['Intervention: +10 pp sealing, vegetation responds', 'Total effect θ', 'Terrain, location (W)', 'W; mediators respond', 'Within-city DML; checks (Figs. 1, 2)'],
             ['Intervention: +10 pp sealing, vegetation kept', 'Direct effect', 'W + NDVI, albedo, tree cover', 'W and mediators', 'Within-city DML (Fig. 1c)'],
             ['Model-implied contrast', 'f(ISA + 0.1, ·) − f(ISA, ·)', 'Model features', 'All other features', 'GBM answers (Fig. 4)'],
             ['Transport to unseen cities', 'τ(V), V = cell and climate modifiers', 'Within-city residuals', 'Linear in V', 'Continent-out tests (Fig. 4, Table 2)'],
             ['Decision: which option?', 'Not estimated', '—', '—', 'Layer separation and caveats (Fig. 6c)']],
            widths_mm=[38, 30, 30, 28, 33], caption='**Table 1 | Planning questions, estimands and conditioning sets.** pp, percentage points; HI, heat-island intensity; ISA, impervious cover; W, terrain and 5-km location bins; V, effect modifiers.')
    rows = []
    for key, lab in [('causal_all', 'Causal transfer'), ('minimal_all', 'GBM minimal'), ('minimal_loc_all', 'GBM minimal + location'), ('partial_all', 'GBM partial'), ('full_all', 'GBM full'),
                     ('full_loc_all', 'GBM full + location'), ('full_mono_all', 'GBM full, monotone'), ('full_joint_all', 'GBM full, mediators shifted'), ('zone_baseline', 'Zone baseline')]:
        v = IV.get(key)
        if not v: continue
        mk = key.replace('_all', '')
        ch = CH.get(f'six|{mk}', {}).get('rho'); chc = CH.get(f'continent|{mk}', {}).get('rho')
        rows.append([lab, B(ch) if ch else '—', B(chc) if chc else '—', B(v['median']), B(v['mae_total']), B(v['mae_direct']), f"{pct(v['sign'][0])} ({pct(v['sign'][1])}–{pct(v['sign'][2])})", B(v['rho'])])
    D.table(['Model', 'ρ change, six out', 'ρ change, continent out', 'Answer to +10 pp (°C)', 'MAD vs own total (°C)', 'MAD vs own direct (°C)', 'Sign agreement', 'ρ with own total'],
            rows, widths_mm=[30, 20, 20, 19, 19, 19, 17, 17], size=7,
            caption=f"**Table 2 | Transfer tests.** ρ change, median Spearman correlation of predicted and observed change of heat-island intensity 1985–2025 in held-out cities' changing cells; answers and errors are for the intervention test with the continent held out, medians or means over {IV['causal_all']['n']} cities with 95% bootstrap intervals over cities in parentheses. MAD, mean absolute difference. Own effects are assumption-dependent benchmarks, not ground truth.")


def build():
    D = Doc(refs=REFS)
    D.para(f'**{TITLE}**', size=14, after=12)
    D.para('Author names and affiliations withheld for double-anonymous review', after=12)
    D.h('Abstract', 1); D.para(ABSTRACT)
    D.h('Main', 1)
    for p in INTRO: D.para(p, after=6)
    D.h('Results', 1)
    sec = [('Defining the intervention and its total effect', R1), ('What the observational checks support', R2), ('Predicting change and answering an intervention are different tasks', R3),
           ('Transferred intervention effects', R4), ('Simulations as assumption checks', R5), ('Heat cost of sealing under climates projected to 2100', R6)]
    for t, ps in sec:
        if not ps: continue
        D.h(t, 2)
        for p in ps: D.para(p, after=6)
    D.h('Discussion', 1)
    for p in DISC: D.para(p, after=6)
    D.h('Limitations', 2); D.para(LIMS, after=6)
    D.h('Conclusions', 2); D.para(CONCL, after=6)
    D.h('Methods', 1)
    for t, ps in METHODS:
        D.h(t, 2)
        for p in ps: D.para(p, after=6)
        if t == 'Within-city causal effects': D.equation(*EQ[0])
        if t == 'Transfer models and tests': D.equation(*EQ[1])
    D.h('Data availability', 1)
    D.para("All input data are openly available: Landsat Collection 2 Level-2, ESA WorldCover 2021, Copernicus GLO-30 DEM, ESA CCI land cover, LCMAP CONUS v1.3, TerraClimate and NEX-GDDP-CMIP6 through the Microsoft Planetary Computer (https://planetarycomputer.microsoft.com), and GlobPOP through Zenodo. Source data for all figures and tables, the city-level estimates and the sampled cell tables are provided with this paper (Source Data) and will be deposited in a public repository upon acceptance.")
    D.h('Code availability', 1)
    D.para("All code for data download, compositing, back-casting, within-city estimation, transfer tests, simulations, projections, figures and tables is provided as Supplementary Software and will be archived with a DOI upon acceptance.")
    D.references()
    D.h('Acknowledgements', 1); D.para('[To be added after review.]')
    D.h('Author contributions', 1); D.para('[To be added after review.]')
    D.h('Competing interests', 1); D.para('The authors declare no competing interests.')
    D.pagebreak(); D.h('Tables', 1); tables(D)
    D.pagebreak(); D.h('Figures', 1)
    for i in range(1, 7): D.figure(f'{FIG}/Fig{i}.png', FIGCAP[i])
    D.pagebreak(); D.h('Extended Data', 1)
    for i in range(1, 9): D.figure(f'{FIG}/ED_Fig{i}.png', ED[i])
    D.save(f'{OUT}/Manuscript_126_cities_revised.docx')
    # word counts
    import itertools
    wc = lambda ps: sum(len(re.sub(r'\[@[^\]]+\]', '', p).split()) for p in ps)
    main = INTRO + R1 + R2 + R3 + R4 + R5 + R6 + DISC + [LIMS, CONCL]
    meth = list(itertools.chain(*[ps for _, ps in METHODS]))
    print('title chars', len(TITLE), 'abstract', len(ABSTRACT.split()), 'main', wc(main), 'methods', wc(meth), 'refs', len(D.order))
    json.dump(dict(order=D.order), open(f'{OUT}/ref_order.json', 'w'))


if __name__ == '__main__':
    build()
